import test from "node:test";
import assert from "node:assert/strict";
import {build,validate,liveSource,media} from "./render.mjs";
const row={id:"3c69be82-a433-4496-b729-58e452f6a0a2",name:"Tomatoes <script>bad</script>",category:"groceries",category_name:"Groceries",availability:"available",regular_price_kes:110,current_price_kes:100,private_field:"secret"};
const path="seo-catalogue/products/"+row.id+"/index.html";
test("staging is noindex and excludes production shopping links",()=>{const f=build([row],"https://staging.invalid",true);assert.ok(f[path].includes("noindex,nofollow"));assert.ok(!f[path].includes("leogo.co.ke"));assert.ok(!f[path].includes("shop-link"));});
test("production product page escapes data and uses live pricing",()=>{const f=build([row],"https://leogo.co.ke");assert.ok(!f[path].includes("<script>"));assert.ok(!f[path].includes("secret"));assert.ok(!f[path].includes("KSh 100"));assert.ok(f[path].includes("product_id="+row.id));assert.ok(f[path].includes("hidden"));assert.ok(f[path].includes("/seo-catalogue/live.js"));});
test("sitemap covers home, catalogue, category, product; removal is reflected",()=>{const f=build([row],"https://leogo.co.ke");assert.ok(f["sitemap.xml"].includes("https://leogo.co.ke/</loc>"));assert.ok(f["sitemap.xml"].includes("/categories/groceries/"));assert.ok(f["sitemap.xml"].includes(row.id));assert.ok(!build([],"https://leogo.co.ke")["sitemap.xml"].includes(row.id));assert.ok(!build([],"https://leogo.co.ke")[path]);assert.ok(Object.keys(f).every(k=>k==="sitemap.xml"||k.startsWith("seo-catalogue/")));});
test("reject restricted categories, duplicate IDs and invalid price",()=>{assert.throws(()=>validate([{...row,category:"alcoholic_leogo_bar"}]));assert.throws(()=>validate([row,row]));assert.throws(()=>validate([{...row,current_price_kes:-1}]));assert.throws(()=>build([row],"https://evil.example"));assert.throws(()=>liveSource("sb_secret_test"));});
test("variant price is not invented",()=>{assert.equal(validate([{...row,current_price_kes:null,regular_price_kes:null,availability:"check_live"}])[0].current_price_kes,null);});

test("live price and eligibility gate", async()=>{
 const source=liveSource("sb_publishable_test");
 async function simulate(rows,ok=true){
  const link={hidden:true,href:""},status={textContent:""},h1={textContent:"Test"},metas=[];
  const el={dataset:{productId:row.id},querySelectorAll:()=>[link]};
  const document={querySelector:s=>s==="h1"?h1:el,querySelectorAll:()=>[],getElementById:s=>s==="live-status"?status:s==="shop-link"?link:null,createElement:()=>({}),head:{append:m=>metas.push(m)},title:"Test"};
  const fetch=async(url,opts)=>{assert.ok(url.startsWith("https://dzdciuqkqixwutvtfotj.supabase.co/"));assert.equal(opts.headers.apikey,"sb_publishable_test");return {ok,json:async()=>rows};};
  new Function("document","fetch",source)(document,fetch);
  for(let i=0;i<10;i++)await Promise.resolve();
  return {link,status,h1,metas};
 }
 let state=await simulate([row]);assert.match(state.status.textContent,/KSh 100/);assert.equal(state.link.hidden,false);assert.match(state.link.href,/product_category=groceries/);
 state=await simulate([{...row,current_price_kes:null,availability:"check_live"}]);assert.match(state.status.textContent,/Select options/);assert.doesNotMatch(state.status.textContent,/KSh/);
 state=await simulate([]);assert.equal(state.link.hidden,true);assert.match(state.status.textContent,/no longer available/);assert.equal(state.metas[0].content,"noindex");
 state=await simulate([],false);assert.equal(state.link.hidden,true);assert.match(state.status.textContent,/Live price unavailable/);
});

test("branded cards use approved image paths and escape options",()=>{const p={...row,image_path:"2a73a05d-0915-4ab2-bbc8-ef60e099ac80/main-test.jpg",gallery:[],variants:[{name:"Red <b>",price_kes:100,available:true}]};const f=build([p],"https://leogo.co.ke");assert.ok(f[path].includes("main-test.jpg"));assert.ok(f[path].includes("Red &lt;b&gt;"));assert.ok(f["seo-catalogue/index.html"].includes("data-catalogue-card"));assert.ok(f["seo-catalogue/catalogue.css"].includes("grid-template-columns"));assert.ok(!build([p],"https://staging.invalid",true)[path].includes("supabase.co"));assert.equal(media("https://evil.test/a.jpg"),"");assert.equal(media("2a73a05d-0915-4ab2-bbc8-ef60e099ac80/../x.jpg"),"");});

test("production discovery metadata is safe and canonical",()=>{const f=build([row],"https://leogo.co.ke");const html=f[path];const match=html.match(/<script type="application\/ld\+json">([\s\S]*?)<\/script>/);assert.ok(match);const data=JSON.parse(match[1]);assert.equal(data["@type"],"BreadcrumbList");assert.equal(data.itemListElement.length,4);assert.equal(data.itemListElement[3].name,row.name);assert.equal(data.itemListElement[3].item,"https://leogo.co.ke/seo-catalogue/products/"+row.id+"/");assert.ok(html.includes('property="og:site_name"'));assert.ok(!match[1].includes('"price"'));assert.ok(!match[1].includes('"offers"'));assert.ok(!html.includes('<script>bad'));assert.ok(!build([row],"https://staging.invalid",true)[path].includes("BreadcrumbList"));});


test("catalogue titles and sharing images support local discovery without staging leakage",()=>{const image_path="2a73a05d-0915-4ab2-bbc8-ef60e099ac80/main-test.jpg",p={...row,image_path};const f=build([p],"https://leogo.co.ke");assert.match(f["seo-catalogue/index.html"],/<title>Shop online in Siaya, Kenya/);assert.match(f["seo-catalogue/categories/groceries/index.html"],/<title>Shop Groceries online in Kenya/);assert.ok(f[path].includes('property="og:image" content="'+media(image_path)+'"'));assert.ok(f["seo-catalogue/index.html"].includes('property="og:image" content="https://leogo.co.ke/assets/images/leogo-official-logo.jpg"'));assert.ok(!build([p],"https://staging.invalid",true)[path].includes('property="og:image"'));});
test("live product rich data uses only matching approved simple-product price and stock",async()=>{const image_path="2a73a05d-0915-4ab2-bbc8-ef60e099ac80/main-test.jpg",p={...row,image_path,variants:[],description:"Public product description"};const source=liveSource("sb_publishable_test");async function simulate(rows,{ok=true,visible=media(image_path),name=row.name}={}){const status={textContent:""},link={hidden:true,href:""},desc={textContent:""},h1={textContent:name},nodes=[];const el={dataset:{productId:row.id},querySelectorAll:()=>[link]};const document={querySelector:s=>s==="h1"?h1:el,querySelectorAll:()=>[],getElementById:s=>({"live-status":status,"shop-link":link,"description":desc,"main-photo":{querySelector:()=>({src:visible})}}[s]||null),createElement:()=>({}),head:{append:n=>nodes.push(n)},title:"Test"};new Function("document","fetch",source)(document,async()=>({ok,json:async()=>rows}));for(let i=0;i<15;i++)await Promise.resolve();return{status,link,nodes,desc,schema:nodes.find(n=>n.type==="application/ld+json")};}let r=await simulate([p]);assert.ok(r.schema);let data=JSON.parse(r.schema.textContent);assert.equal(data["@type"],"Product");assert.equal(data.name,row.name);assert.equal(data.offers.price,100);assert.equal(data.offers.priceCurrency,"KES");assert.equal(data.offers.availability,"https://schema.org/InStock");assert.equal(data.offers.url,"https://leogo.co.ke/seo-catalogue/products/"+row.id+"/");assert.equal(data.image[0],media(image_path));assert.equal(data.description,r.desc.textContent);assert.ok(!r.schema.textContent.includes("secret"));assert.ok(!r.schema.textContent.includes("aggregateRating"));assert.ok(r.status.textContent.includes("KSh 100"));assert.equal(r.link.hidden,false);r=await simulate([{...p,current_price_kes:75,availability:"out_of_stock"}],{visible:media(image_path+"-opt.webp")});data=JSON.parse(r.schema.textContent);assert.equal(data.offers.price,75);assert.equal(data.offers.availability,"https://schema.org/OutOfStock");assert.equal(data.image[0],media(image_path+"-opt.webp"));for(const bad of [{...p,current_price_kes:null},{...p,current_price_kes:0},{...p,current_price_kes:2.333},{...p,availability:"check_live"},{...p,variants:[{name:"Large",price_kes:100,available:true}]},{...p,image_path:null},{...p,name:"Renamed product"}]){r=await simulate([bad]);assert.equal(r.schema,undefined);assert.equal(r.link.hidden,false);}assert.equal((await simulate([p],{visible:"https://evil.example/photo.jpg"})).schema,undefined);r=await simulate([]);assert.equal(r.schema,undefined);assert.equal(r.link.hidden,true);assert.equal(r.nodes[0].content,"noindex");r=await simulate([p],{ok:false});assert.equal(r.schema,undefined);assert.equal(r.link.hidden,true);});
